## 3. Formatação de Resposta para Melhor Legibilidade

```javascript
// utils/text-formatter.js
function createFormattedResponse(data, interaction) {
  const responseEmbeds = [];

  // Título principal
  responseEmbeds.push({
    title: "📄 Resumo do PDF",
    description: `O conteúdo foi extraído com sucesso!`,
    color: 5814783,
    footer: { text: `Bot processado • ${new Date().toLocaleString()} ` },
    timestamp: new Date()
  });

  // Conteúdo organizado por seções
  Object.entries(data).forEach(([section, value]) => {
    if (!value) return;

    let embed = {
      title: `**${section.toUpperCase()}**`,
      description: typeof value === 'string' ? value : JSON.stringify(value, null, 2),
      color: Math.floor(Math.random() * 0xffffff),
      fields: []
    };

    // Se for objeto ou array, formatar com campos
    if (Array.isArray(value)) {
      value.forEach((item, idx) => {
        embed.fields.push({
          name: `Item ${idx + 1}:`,
          value: typeof item === 'string' ? item : String(item),
          inline: false
        });
      });
    } else if (typeof value === 'object') {
      embed.fields.push(
        { name: 'Chave:', value: 'Objeto JSON', inline: false },
        ...Object.entries(value).map(([k, v]) => ({
          name: `${k.replace(/_/g, ' ')}`,
          value: String(v),
          inline: true
        }))
      );
    }

    responseEmbeds.push(embed);
  });

  return interaction.reply({
    content: '',
    embeds: responseEmbeds
  });
}
